    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load tile from A and B into shared memory
        int tile_offset = tile * TILE_SIZE;
        int A_row_idx = row;
        int A_col_idx = tile_offset + threadIdx.x;
        int B_row_idx = tile_offset + threadIdx.y;
        int B_col_idx = col;

        // Check bounds for A
        if (A_row_idx < N && A_col_idx < N) {
            As[threadIdx.y][threadIdx.x] = A[A_row_idx * N + A_col_idx];
